mapper.select:
SELECT id, kind, payload, occurred_at AS occurredAt
FROM transcript_entry
WHERE platform = #{platform}
  AND bot_id = #{botId}
  AND group_id = #{groupId}
  AND id >= #{firstEntryId}
  AND id <= #{lastEntryId}
ORDER BY id

SELECT id, kind, payload, occurred_at AS occurredAt
FROM transcript_entry
WHERE platform = #{platform}
  AND bot_id = #{botId}
  AND group_id = #{groupId}
  AND id > #{afterId}
ORDER BY id
    LIMIT #{limit}

SELECT MAX(id)
FROM transcript_entry
WHERE platform = #{platform}
  AND bot_id = #{botId}
  AND group_id = #{groupId}

SELECT id, kind, payload, occurred_at AS occurredAt
FROM transcript_entry
WHERE platform = #{platform}
  AND bot_id = #{botId}
  AND group_id = #{groupId}
  AND kind = 'user'
  AND occurred_at >= #{since}
ORDER BY id
    LIMIT #{limit}
